sparql.content:
# Indicator: NZA WMG 2.1
# Parameters: ?jaar
# Ontologie: versie 3.0.0 of nieuwer

PREFIX onz-g: <http://purl.org/ozo/onz-g#>
PREFIX onz-zorg: <http://purl.org/ozo/onz-zorg#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    (SUM(?is_zvw) AS ?Aantal_clienten_Zvw)
    (SUM(?is_wlz) AS ?Aantal_clienten_Wlz)
    (SUM(?is_fis) AS ?Aantal_clienten_Forensische_zorg)
    (SUM(?is_overig) AS ?Aantal_clienten_Overige_zorg)
WHERE {
    SELECT
        (MAX(IF(BOUND(?wlz), 1, 0)) AS ?is_wlz)
        (MAX(IF(BOUND(?zvw), 1, 0)) AS ?is_zvw)
        (MAX(IF(BOUND(?fis), 1, 0)) AS ?is_fis)
        (IF(?is_wlz + ?is_zvw + ?is_fis = 0, 1, 0) AS ?is_overig)
    WHERE {
        # BIND(2024 AS ?jaar) .  # Parameter

        BIND(STRDT(CONCAT(STR(?jaar), "-01-01"), xsd:date) AS ?start_datum) .
        BIND(?start_datum + "P1Y"^^xsd:duration - "P1D"^^xsd:duration AS ?eind_datum)

        {
            ?indicatie a onz-zorg:IndicatieBesluit 
        } UNION {
            ?indicatie a onz-zorg:ForensischeIndicatieStelling
        }
        ?indicatie
            onz-g:isAbout ?client ;
            onz-g:startDatum ?start_indicatie .
        OPTIONAL { ?indicatie onz-g:eindDatum ?eind_indicatie . }
        FILTER (?start_indicatie <= ?eind_datum && (!BOUND(?eind_indicatie) || ?eind_indicatie >= ?start_datum))

        ?client a onz-g:Human .
        OPTIONAL {
            ?indicatie a onz-zorg:WlzIndicatie .
            BIND(1 AS ?wlz) .
        }
        OPTIONAL {
            ?indicatie a onz-zorg:ZvwIndicatie .
            BIND(1 AS ?zvw) .
        }
        OPTIONAL {
            ?indicatie a onz-zorg:ForensischeIndicatieStelling .
            BIND(1 AS ?fis) .
        }
    } GROUP BY ?client
}

